from collections import defaultdict

def solve(allow_rot, maxsol=3, nodecap=2000000):
 pl=getplacements(allow_rot); bycell=defaultdict(list)
 for i,(t,cells,info) in enumerate(pl):
  for cell in cells: bycell[cell].append(i)
 rem=types.copy(); covered=set(); sol=[]; nnode=0; sols=[]
 def rec():
  nonlocal nnode
  nnode+=1
  if nnode>nodecap:return True
  if len(covered)==len(mask):
   if not any(rem.values()): sols.append(sol.copy())
   return len(sols)>=maxsol
  best=None;optsbest=None
  for cell in mask-covered:
   opts=[]
   for i in bycell[cell]:
    t,cells,info=pl[i]
    if rem[t] and not (cells&covered): opts.append(i)
   if not opts:return False
   if optsbest is None or len(opts)<len(optsbest):best=cell;optsbest=opts
   if len(optsbest)==1:break
  for i in optsbest:
   t,cells,info=pl[i]
   rem[t]-=1;covered.update(cells);sol.append((t,info))
   stop=rec()
   sol.pop();covered.difference_update(cells);rem[t]+=1
   if stop:return True
  return False
 rec()
 return sols,nnode
